<script setup lang="ts">
import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { demoReset } from '../services/demoAuth'; import AuthShell from '../components/AuthShell.vue'
const route = useRoute(); const router = useRouter(); const email = ref(String(route.query.email || '')); const code = ref(''); const password = ref(''); const message = ref(''); const error = ref('')
async function reset() { error.value = ''; try { if (password.value.length < 10) throw new Error('La contraseña debe tener al menos 10 caracteres.'); await demoReset(email.value, code.value, password.value); message.value = 'Contraseña actualizada. Ya puedes iniciar sesión.'; setTimeout(() => router.push('/login'), 1200) } catch (e: any) { error.value = e.message } }
</script>
<template><AuthShell eyebrow="NUEVA CONTRASEÑA" title="Restablece el acceso" subtitle="Introduce el código recibido y crea una contraseña segura."><v-alert v-if="message" type="success" variant="tonal" class="mb-5">{{ message }}</v-alert><v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{ error }}</v-alert><v-form @submit.prevent="reset"><v-text-field v-model="email" label="Correo" variant="outlined" /><v-text-field v-model="code" label="Código de 6 dígitos" variant="outlined" /><v-text-field v-model="password" label="Nueva contraseña" type="password" variant="outlined" hint="Mínimo 10 caracteres" persistent-hint /><v-btn type="submit" block color="primary" size="large" rounded="lg" class="text-none font-weight-bold mt-5">Actualizar contraseña</v-btn></v-form></AuthShell></template>
